import{_ as o,C as s,o as t,c as n,a3 as a,b as i,w as d,a as l,E as h,a4 as c}from"./chunks/framework.DhF4LrUq.js";const A=JSON.parse('{"title":"OTA updates","description":"OTA updates - signed platform-agnostic bundles an app applies itself, distributed through the ordinary release machinery with a staged device rollout and a monitored funnel.","frontmatter":{"description":"OTA updates - signed platform-agnostic bundles an app applies itself, distributed through the ordinary release machinery with a staged device rollout and a monitored funnel."},"headers":[],"relativePath":"concepts/ota-updates.md","filePath":"concepts/ota-updates.md"}'),p={name:"concepts/ota-updates.md"};function u(g,e,b,m,f,v){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a('<h1 id="ota-updates" tabindex="-1">OTA updates <a class="header-anchor" href="#ota-updates" aria-label="Permalink to &quot;OTA updates&quot;">​</a></h1><p>Some apps can update themselves: React Native, Flutter, and Electron-style apps ship a runtime that applies new content and logic without waiting on a store review. For those, ShipperDog distributes OTA (over-the-air) updates — platform-agnostic bundles governed, signed, staged, and monitored with exactly the same rigor as store releases.</p><p>The choice is mechanical: send what the app can apply at runtime (a JS bundle, refreshed assets) as an OTA bundle; send anything that changes the native binary through the ordinary store-release path. An OTA bundle is never a side channel — it rides the same releases, approvals, and gates everything else rides.</p><p>OTA is opt-in per application: the application&#39;s OTA toggle is turned on in the console, and the app gets an app-scoped Ed25519 signing key (the private half stays inside ShipperDog&#39;s secret store; the public half is copyable from the console for embedding in the app).</p><h2 id="from-bundle-to-release" tabindex="-1">From bundle to release <a class="header-anchor" href="#from-bundle-to-release" aria-label="Permalink to &quot;From bundle to release&quot;">​</a></h2><p>An OTA update is a bundle with its own lifecycle:</p><table tabindex="0"><thead><tr><th>Stage</th><th>What is true</th></tr></thead><tbody><tr><td>Draft</td><td>The author uploads a platform-agnostic archive; it gets its own version row, a version label, a platform tag, and a minimum store version.</td></tr><tr><td>Signed</td><td>Finalize computes the sha256 and size, then signs with the app&#39;s Ed25519 key. Only a signed bundle can publish.</td></tr><tr><td>Released</td><td>The bundle publishes on an ordinary release over a ring whose distribution channel is <code>ota</code> — exactly one bundle per OTA release.</td></tr></tbody></table><p>Because an OTA release is an ordinary release, the whole governance stack applies unchanged: approval workflows, quality gates, policies, and status history all guard it, and the release dashboard reads the same as any other. Widening the audience is the same ring promotion; pulling it back is the same rollback crossing.</p><p>Two withdrawal rules follow from that linkage: a signed-but-unreleased bundle is the author&#39;s to revoke, while a released bundle belongs to its release — pulling it back is the release&#39;s rollback, not a bundle delete. The rollout can also be halted (below), which stops new devices from seeing the update without touching the release.</p><h2 id="the-device-flow" tabindex="-1">The device flow <a class="header-anchor" href="#the-device-flow" aria-label="Permalink to &quot;The device flow&quot;">​</a></h2><p>The shipped app carries an <code>sdc1.</code> app token — an identifier, not a secret — and polls one endpoint, <code>GET /api/v1/ota/check</code>, on a server-owned cadence (the manifest returns <code>pollIntervalSeconds</code>, default 3600):</p>',11)),(t(),i(c,null,{default:d(()=>[h(r,{id:"mermaid-68",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20A%20as%20App%20(device)%0A%20%20%20%20participant%20S%20as%20ShipperDog%20API%0A%20%20%20%20participant%20U%20as%20Bundle%20storage%0A%20%20%20%20participant%20T%20as%20Telemetry%20ingest%0A%0A%20%20%20%20A-%3E%3ES%3A%20GET%20%2Fapi%2Fv1%2Fota%2Fcheck%20(Bearer%20sdc1...%20deviceId%2C%20platform%2C%20appVersion%2C%20channel)%0A%20%20%20%20alt%20no%20update%20stands%0A%20%20%20%20%20%20%20%20S--%3E%3EA%3A%20204%20No%20Content%20%E2%80%94%20every%20reason%20indistinguishable%0A%20%20%20%20else%20an%20update%20stands%20for%20this%20device%0A%20%20%20%20%20%20%20%20S--%3E%3EA%3A%20200%20%2B%20manifest%20(bundleId%2C%20url%2C%20sha256%2C%20signature%2C%20keyId%2C%20ingestToken)%0A%20%20%20%20%20%20%20%20A-%3E%3ET%3A%20OTA_SEEN%20(the%20sdt1.%20grant%20the%20manifest%20minted)%0A%20%20%20%20%20%20%20%20A-%3E%3EU%3A%20Download%20the%20bundle%20via%20the%20short-lived%20signed%20URL%0A%20%20%20%20%20%20%20%20A-%3E%3EA%3A%20Verify%20sha256%2C%20then%20the%20Ed25519%20signature%20by%20keyId%0A%20%20%20%20%20%20%20%20A-%3E%3EA%3A%20Apply%20through%20the%20app's%20own%20callback%0A%20%20%20%20%20%20%20%20A-%3E%3ET%3A%20OTA_DOWNLOAD%2C%20OTA_APPLIED%20%E2%80%94%20or%20OTA_FAILED%20%2F%20OTA_ROLLED_BACK%0A%20%20%20%20end%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>The manifest tells the device everything it needs:</p><table tabindex="0"><thead><tr><th>Member</th><th>Meaning</th></tr></thead><tbody><tr><td><code>bundleId</code> / <code>bundleVersion</code></td><td>The served bundle&#39;s id and version label — every lifecycle report attributes back through <code>bundleId</code>.</td></tr><tr><td><code>url</code></td><td>A short-lived signed download URL, minted for this check.</td></tr><tr><td><code>sha256</code> / <code>sizeBytes</code></td><td>Verify the downloaded bytes end to end.</td></tr><tr><td><code>signature</code> / <code>keyId</code></td><td>The Ed25519 signature over the sha256, and which signing-key generation made it.</td></tr><tr><td><code>forced</code> / <code>minAppVersion</code></td><td>Whether the update must apply, and the oldest store version it applies to — defaults from the bundle, overridable per release target.</td></tr><tr><td><code>ingestToken</code></td><td>A short-lived <code>sdt1.</code> grant for reporting this update&#39;s lifecycle.</td></tr><tr><td><code>pollIntervalSeconds</code></td><td>When to check again.</td></tr></tbody></table><p>The 204 is deliberately opaque: up to date, not eligible, a paused or halted rollout, a stage the device has not reached, or no live release — all the same bytes, because the split lives in ShipperDog&#39;s server-side counters, never on the wire. A malformed request is the one coded error the check returns; a bad token is the ordinary 401.</p><p>Verification is end to end: the device checks the sha256 and the Ed25519 signature against the public key embedded in the app — the signature is never just transport trust. Signing keys rotate by generation: a new <code>keyId</code> supersedes, and old signatures stay verifiable against the retained public half until the generation retires.</p><h2 id="staged-device-rollout" tabindex="-1">Staged device rollout <a class="header-anchor" href="#staged-device-rollout" aria-label="Permalink to &quot;Staged device rollout&quot;">​</a></h2><p>One rollout plan per OTA release: a ladder of cumulative stages, each a basis-point threshold (10000 = everyone), advanced manually or automatically per the plan&#39;s mode. Which devices a stage covers is decided on the fly, deterministically:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(deviceId, planSalt) mod 10000 &lt; stage.basisPoints</span></span></code></pre></div><p>The same device lands in the same bucket for the life of the plan — no cohort table, nothing to backfill — and a device below the current stage&#39;s threshold gets the same 204 as an up-to-date device.</p><table tabindex="0"><thead><tr><th>Standing</th><th>What it means</th></tr></thead><tbody><tr><td>Running</td><td>Stages admit devices per the ladder.</td></tr><tr><td>Paused</td><td>Devices hold; already-served devices keep their manifest.</td></tr><tr><td>Halted</td><td>The human stop. Every control crossing is audit-trailed.</td></tr><tr><td>Complete</td><td>The ladder reached everyone.</td></tr></tbody></table><p>Pause, resume, advance, and halt are one-action controls from the console or CLI. Halting is deliberately manual: alert rules watch failure rates and crash-free regressions and page a human through the notification bus, but no threshold ever stops a rollout by itself — the halt is one audited action away.</p><h2 id="watching-the-funnel" tabindex="-1">Watching the funnel <a class="header-anchor" href="#watching-the-funnel" aria-label="Permalink to &quot;Watching the funnel&quot;">​</a></h2><p>The funnel&#39;s two halves come from different places by design. Checks are counted server-side; the device-side journey — seen, download, apply, fail, roll back — is reported by the app as lifecycle telemetry through the ordinary analytics ingest. The OTA dashboard reads both halves together, and alert rules turn degradation signals into notifications for a human to act on.</p><p>v1 ships full bundles only: a device always downloads the complete archive. Delta bundles are a recorded future direction, not current behavior.</p><h2 id="where-to-go-deeper" tabindex="-1">Where to go deeper <a class="header-anchor" href="#where-to-go-deeper" aria-label="Permalink to &quot;Where to go deeper&quot;">​</a></h2><ul><li><a href="/shipperdog/snapshot/concepts/release-lifecycle">Release lifecycle</a> — the machine every OTA release rides</li><li><a href="/shipperdog/snapshot/concepts/rings-and-rollout">Rings and rollout</a> — the promotion ladder an <code>ota</code>-channel ring sits on</li><li><a href="/shipperdog/snapshot/concepts/feedback-analytics">Feedback and analytics</a> — the telemetry loop the lifecycle reports join</li><li><a href="/shipperdog/snapshot/reference/error-codes">Error codes</a> — the OTA codes a console operator meets</li><li>Developer detail: the <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/ota.md" target="_blank" rel="noreferrer">OTA device contract</a> and <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs/adr/ADR-0010-ota-updates.md" target="_blank" rel="noreferrer">ADR-0010</a> — the full wire reference and the decision record.</li></ul>',15))])}const T=o(p,[["render",u]]);export{A as __pageData,T as default};
